begin;
create table public.restore_tickets(label text primary key,ticket jsonb);
create table public.old_review as select generation_id from cs_promo_private.review_heads where plan_id='00000000-0000-0000-0000-000000000021';
insert into restore_tickets values('stop',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','withdraw','00000000-0000-0000-0000-000000000001'));
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is not null,'explicit preclaim stop') from restore_tickets;
insert into restore_tickets values('restore',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','restore','00000000-0000-0000-0000-000000000001'));
select public.assert_ok((public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001')->>'reviewRequired')::boolean,'explicit restore requires fresh review') from restore_tickets where label='restore';
select public.assert_ok((select invalidated from cs_promo_private.review_versions where id=(select generation_id from old_review)),'restored old generation stays invalid');
select public.assert_ok(public.cs_read_character_promo_approval('00000000-0000-0000-0000-000000000021') is null,'restored old final approval never revives');
select public.assert_ok(public.cs_claim_character_promo('00000000-0000-0000-0000-000000000021',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000021')) is null,'restore cannot dispatch old consent');
select public.assert_ok(public.cs_begin_character_promo_review('00000000-0000-0000-0000-000000000021',public.content_for('00000000-0000-0000-0000-000000000021'),repeat('c',64),public.expected_for('00000000-0000-0000-0000-000000000021'),'00000000-0000-0000-0000-000000000001')->>'generationId' is not null,'new explicit generation after restore');
select public.assert_ok((select generation_id<>(select generation_id from old_review) from cs_promo_private.review_heads where plan_id='00000000-0000-0000-0000-000000000021'),'restoration uses distinct generation');
select public.assert_ok((select count(*)=0 from cs_promo_private.gates where generation_id=(select generation_id from cs_promo_private.review_heads where plan_id='00000000-0000-0000-0000-000000000021')),'new generation has zero confirmations');
select public.assert_ok((select count(*)=3 from cs_promo_private.gates where generation_id=(select generation_id from old_review)),'prior gate evidence preserved');
insert into restore_tickets values('stop-again',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','withdraw','00000000-0000-0000-0000-000000000001'));
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is not null,'explicit stop again before dispatch') from restore_tickets where label='stop-again';
insert into restore_tickets values('old-restore',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','restore','00000000-0000-0000-0000-000000000001'));
select public.assert_ok(public.cs_claim_character_promo('00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020')) is not null,'active peer dispatch starts after old restore preview');
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001')->>'status'='shared_dispatch_started','old restore ticket loses to first shared claim') from restore_tickets where label='old-restore';
select public.assert_ok(cs_promo_private.plan_withdrawn('00000000-0000-0000-0000-000000000021'),'frozen cohort not expanded by stale restore');
commit;
